-- Permission vocabulary and system roles of the timesheet module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the timesheet permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('rate_card:create'::text, 'rate_card'::text, 'create'::text, 'Create rate card'::text),
            ('rate_card:delete'::text, 'rate_card'::text, 'delete'::text, 'Delete rate card'::text),
            ('rate_card:purge'::text, 'rate_card'::text, 'purge'::text, 'Purge rate card'::text),
            ('rate_card:read'::text, 'rate_card'::text, 'read'::text, 'Read rate card'::text),
            ('rate_card:restore'::text, 'rate_card'::text, 'restore'::text, 'Restore rate card'::text),
            ('rate_card:update'::text, 'rate_card'::text, 'update'::text, 'Update rate card'::text),
            ('timesheet:create'::text, 'timesheet'::text, 'create'::text, 'Create timesheet'::text),
            ('timesheet:delete'::text, 'timesheet'::text, 'delete'::text, 'Delete timesheet'::text),
            ('timesheet:purge'::text, 'timesheet'::text, 'purge'::text, 'Purge timesheet'::text),
            ('timesheet:read'::text, 'timesheet'::text, 'read'::text, 'Read timesheet'::text),
            ('timesheet:restore'::text, 'timesheet'::text, 'restore'::text, 'Restore timesheet'::text),
            ('timesheet:update'::text, 'timesheet'::text, 'update'::text, 'Update timesheet'::text),
            ('timesheet_approval:create'::text, 'timesheet_approval'::text, 'create'::text, 'Create timesheet approval'::text),
            ('timesheet_approval:delete'::text, 'timesheet_approval'::text, 'delete'::text, 'Delete timesheet approval'::text),
            ('timesheet_approval:purge'::text, 'timesheet_approval'::text, 'purge'::text, 'Purge timesheet approval'::text),
            ('timesheet_approval:read'::text, 'timesheet_approval'::text, 'read'::text, 'Read timesheet approval'::text),
            ('timesheet_approval:restore'::text, 'timesheet_approval'::text, 'restore'::text, 'Restore timesheet approval'::text),
            ('timesheet_approval:update'::text, 'timesheet_approval'::text, 'update'::text, 'Update timesheet approval'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('rate_card:create'::text, 'rate_card'::text, 'create'::text, 'Create rate card'::text),
            ('rate_card:delete'::text, 'rate_card'::text, 'delete'::text, 'Delete rate card'::text),
            ('rate_card:purge'::text, 'rate_card'::text, 'purge'::text, 'Purge rate card'::text),
            ('rate_card:read'::text, 'rate_card'::text, 'read'::text, 'Read rate card'::text),
            ('rate_card:restore'::text, 'rate_card'::text, 'restore'::text, 'Restore rate card'::text),
            ('rate_card:update'::text, 'rate_card'::text, 'update'::text, 'Update rate card'::text),
            ('timesheet:create'::text, 'timesheet'::text, 'create'::text, 'Create timesheet'::text),
            ('timesheet:delete'::text, 'timesheet'::text, 'delete'::text, 'Delete timesheet'::text),
            ('timesheet:purge'::text, 'timesheet'::text, 'purge'::text, 'Purge timesheet'::text),
            ('timesheet:read'::text, 'timesheet'::text, 'read'::text, 'Read timesheet'::text),
            ('timesheet:restore'::text, 'timesheet'::text, 'restore'::text, 'Restore timesheet'::text),
            ('timesheet:update'::text, 'timesheet'::text, 'update'::text, 'Update timesheet'::text),
            ('timesheet_approval:create'::text, 'timesheet_approval'::text, 'create'::text, 'Create timesheet approval'::text),
            ('timesheet_approval:delete'::text, 'timesheet_approval'::text, 'delete'::text, 'Delete timesheet approval'::text),
            ('timesheet_approval:purge'::text, 'timesheet_approval'::text, 'purge'::text, 'Purge timesheet approval'::text),
            ('timesheet_approval:read'::text, 'timesheet_approval'::text, 'read'::text, 'Read timesheet approval'::text),
            ('timesheet_approval:restore'::text, 'timesheet_approval'::text, 'restore'::text, 'Restore timesheet approval'::text),
            ('timesheet_approval:update'::text, 'timesheet_approval'::text, 'update'::text, 'Update timesheet approval'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
